CREATE TABLE IF NOT EXISTS ai_drafts (id TEXT PRIMARY KEY, class_id TEXT NOT NULL, chapter_id TEXT, created_by TEXT NOT NULL, draft_type TEXT NOT NULL CHECK (draft_type IN ('insight', 'activity')), title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', payload TEXT NOT NULL DEFAULT '{}', source_refs TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'confirmed', 'rejected')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, reviewed_at TEXT, reviewed_by TEXT, FOREIGN KEY (class_id) REFERENCES classes(id), FOREIGN KEY (chapter_id) REFERENCES chapters(id), FOREIGN KEY (created_by) REFERENCES users(id), FOREIGN KEY (reviewed_by) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_ai_drafts_class_status ON ai_drafts(class_id, status, updated_at);
